// src/resample.ts
function resampleLinear(src, srcRate, dstRate) {
  if (srcRate === dstRate) return src;
  if (src.length === 0) return src;
  const ratio = srcRate / dstRate;
  const outLen = Math.max(1, Math.floor(src.length / ratio));
  const out = new Float32Array(outLen);
  for (let i = 0; i < outLen; i++) {
    const pos = i * ratio;
    const i0 = Math.floor(pos);
    const i1 = Math.min(i0 + 1, src.length - 1);
    const frac = pos - i0;
    out[i] = src[i0] + (src[i1] - src[i0]) * frac;
  }
  return out;
}

// src/wakeword.ts
var WAKE_LEAD_CHARS = 3;
var WAKE_MAX_EDITS = 1;
function splitWakeWords(value) {
  return value.split(/[;；]/).map((word) => word.trim()).filter(Boolean);
}
function normalizeWake(text) {
