  const r = new Float32Array(N);
  let mSum = 0;
  let rSum = 0;
  for (let i = 0; i < N; i++) {
    let mv = 0;
    let rv = 0;
    for (let k = 0; k < ds; k++) {
      mv += mic[i * ds + k];
      rv += ref[i * ds + k];
