const textOf = message => message?.content?.filter(item => item.type === 'text').map(item => item.text).join('') ?? ''
const isConfirmation = message => message?.source?.kind === 'user' && textOf(message).trim() === '确认执行'

function toolValue(event) {
  const message = event?.data?.message
  if (message?.source?.kind !== 'tool' || message.isError) return null
  const block = message.content?.find(item => item.type === 'tool-result' && item.toolCallId === message.source.callId)
  if (block?.isError) return null
  const content = block ? block.content : message.content
  try {
    const raw = JSON.parse(content?.find(item => item.type === 'text')?.text)
    return raw?.code === '200' && raw.data ? raw.data : raw
  } catch { return null }
}

export function latestDraft(events, confirmingMessageId) {
  const calls = new Map()
  const views = []
  for (const event of events) {
    if (event.type === 'tool/call') calls.set(event.data?.callId, event.data)
    if (event.type !== 'tool/result') continue
    const call = calls.get(event.data?.message?.source?.callId)
    if (!call || ![PREPARE, REVISE, CANCEL, GET, RESULT].includes(call.name)) continue
    let args
    try { args = JSON.parse(call.arguments) } catch { continue }
    const value = toolValue(event)
    if (value && (call.name === PREPARE ? args?.body?.request_id : args?.operationId === value.operation_id)) {
      views.push({ ...value, seq: event.seq })
    }
  }
  const current = views.at(-1)
  const laterUsers = current && events.filter(event => event.type === 'user/message' &&
    event.data?.source?.kind === 'user' && event.seq > current.seq)
  const currentVisible = laterUsers?.some(event => event.data.id === confirmingMessageId)
  const confirmationsOnly = laterUsers?.every(event => isConfirmation(event.data)) &&
    (!currentVisible || laterUsers.at(-1).data.id === confirmingMessageId)
  if (!current || !confirmationsOnly ||
      events.some(event => event.type === 'tool/call' && event.seq > current.seq &&
        [PREPARE, REVISE, CANCEL].includes(event.data?.name)) ||
      current.phase !== 'READY' ||
      current.execution_status !== 'NOT_SUBMITTED' ||
      !/^op_[a-f0-9]{32}$/.test(current.operation_id ?? '') ||
      !Number.isInteger(current.version) || current.version < 1 ||
      !/^sha256:[a-f0-9]{64}$/.test(current.snapshot_digest ?? '') ||
      !current.snapshot || !Number.isFinite(Date.parse(current.expires_at)) ||
      Date.parse(current.expires_at) <= Date.now()) return null
  if (views.some(item => item.operation_id === current.operation_id && item.version > current.version)) return null
  return { operationId: current.operation_id, version: current.version,
    snapshotDigest: current.snapshot_digest, expiresAt: current.expires_at }
}

function keyFor(sessionId, draft) {
  return createHash('sha256').update(`${sessionId}\n${draft.operationId}\n${draft.version}\n${draft.snapshotDigest}`).digest('hex')
}

export function confirmationPayload(sessionId, draft, now = Date.now()) {
  const id = keyFor(sessionId, draft)
  return {
    audience: 'emergency-confirmation-v1', event_type: 'UserPromptSubmit', decision: 'CONFIRM',
    tenant_id: process.env.AI_WORKBENCH_EMERGENCY_TENANT_ID,
    workspace_id: process.env.AI_WORKBENCH_EMERGENCY_WORKSPACE_ID,
    user_id: process.env.EMERGENCY_CONFIRMATION_ACTOR_ID,
    session_id: sessionId, event_id: `dsh-${id}`,
    operation_id: draft.operationId, version: draft.version,
    snapshot_digest: draft.snapshotDigest,
    issued_at: Math.floor(now / 1000), expires_at: Math.floor(now / 1000) + 120,
  }
}

function proofFor(payload) {
  const encoded = Buffer.from(JSON.stringify(payload)).toString('base64url')
  const pem = Buffer.from(process.env.EMERGENCY_CONFIRMATION_PRIVATE_KEY_B64 ?? '', 'base64')
  const privateKey = createPrivateKey(pem)
  return `${encoded}.${sign('sha256', Buffer.from(encoded, 'ascii'), privateKey).toString('base64url')}`
}

async function saveState(path, state) {
  await mkdir(STATE_DIR, { recursive: true, mode: 0o700 })
  const temporary = `${path}.${randomUUID()}.tmp`
  await writeFile(temporary, JSON.stringify(state), { mode: 0o600, flag: 'wx' })
  await chmod(temporary, 0o600)
  await rename(temporary, path)
}

function validateResponse(value, draft) {
  if (value?.operation_id !== draft.operationId || value.version !== draft.version ||
      value.snapshot_digest !== draft.snapshotDigest ||
      !['QUEUED', 'SUBMISSION_UNKNOWN', 'ACCEPTED', 'TERMINAL'].includes(value.phase)) {
    throw new Error('Workbench 确认回执与当前草案不一致')
  }
  return value
}

async function confirm(sessionId, draft) {
  const path = join(STATE_DIR, `${keyFor(sessionId, draft)}.json`)
  try { return JSON.parse(await readFile(path, 'utf8')) } catch { /* First confirmation. */ }
  const id = keyFor(sessionId, draft)
  const requestId = `dsh-emergency-${id.slice(0, 32)}`
  let state
  try {
    const url = process.env.EMERGENCY_WORKBENCH_URL
    const token = process.env.EMERGENCY_WORKBENCH_TOKEN
    if (!url || !token || !process.env.EMERGENCY_CONFIRMATION_PRIVATE_KEY_B64 ||
        !process.env.EMERGENCY_CONFIRMATION_ACTOR_ID ||
        !process.env.AI_WORKBENCH_EMERGENCY_TENANT_ID ||
        !process.env.AI_WORKBENCH_EMERGENCY_WORKSPACE_ID) throw new Error('确认运行时配置不完整')
    const response = await fetch(`${url.replace(/\/$/, '')}/api/v1/emergency-actions/${draft.operationId}/confirmations`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ request_id: requestId, expected_version: draft.version,
        snapshot_digest: draft.snapshotDigest,
        confirmation_event_ref: proofFor(confirmationPayload(sessionId, draft)) }),
      signal: AbortSignal.timeout(30000),
    })
    if (!response.ok) throw new Error(`Workbench 确认接口返回 HTTP ${response.status}`)
    const view = validateResponse(await response.json(), draft)
    state = { operationId: draft.operationId, requestId, phase: view.phase,
      approvalStatus: view.approval_status, executionStatus: view.execution_status,
      message: formatConfirmationStatus(null, view) }
  } catch (error) {
    // A timed-out response can arrive after Workbench accepted the request.
    state = { operationId: draft.operationId, requestId,
      message: `确认接口未返回有效回执：${error.message}。操作号 ${draft.operationId}；提交结果待查账，请勿重复确认。` }
  }
  await saveState(path, state)
  return state
}

export function formatConfirmationStatus(state, view) {
  if (!view || (!state?.phase && view.phase === 'READY')) return state?.message ?? '确认结果待查账，请稍后按操作号查询。'
  const socStatus = view.soc_observation?.evidence?.status
  let result
  if (socStatus === 'SUCCESS') result = '执行结果：成功'
  else if (socStatus === 'FAILED' || socStatus === 'BLOCKED') result = '执行结果：失败'
  else if (socStatus === 'REJECTED') result = '执行结果：审批已拒绝，未执行'
  else if (socStatus === 'RUNNING') result = '当前进度：执行中'
  else if (socStatus === 'AWAITING_APPROVAL') result = '当前进度：待审批'
  else if (view.execution_status === 'SUCCEEDED') result = '执行结果：成功'
  else if (view.execution_status === 'FAILED') result = '执行结果：失败'
  else if (view.approval_status === 'REJECTED') result = '执行结果：审批已拒绝，未执行'
  else if (view.execution_status === 'RUNNING') result = '当前进度：执行中'
  else if (view.approval_status === 'PENDING') result = '当前进度：待审批'
  else if (view.phase === 'SUBMISSION_UNKNOWN') result = '当前进度：提交结果待核实，请稍后查询'
  else result = '当前进度：处理中，请稍后查询'
  const ids = [`操作号：${view.operation_id}`]
  if (view.soc_execution_id) ids.push(`SOC 执行号：${view.soc_execution_id}`)
  return `${result}\n${ids.join('；')}`
}

export async function latestConfirmationStatus(draft, state, options = {}) {
  const fetchImpl = options.fetchImpl ?? fetch
  const sleep = options.sleep ?? (ms => new Promise(resolve => setTimeout(resolve, ms)))
  const deadline = Date.now() + (options.waitMs ?? 30000)
  let latest = null
  const url = process.env.EMERGENCY_WORKBENCH_URL
  const token = process.env.EMERGENCY_WORKBENCH_TOKEN
  if (!url || !token) return null
  do {
    try {
      const response = await fetchImpl(`${url.replace(/\/$/, '')}/api/v1/emergency-actions/${draft.operationId}/result`, {
        headers: { Authorization: `Bearer ${token}` }, signal: AbortSignal.timeout(3000),
      })
      if (!response.ok) break
      latest = validateResponse(await response.json(), draft)
      if (latest.phase === 'TERMINAL' || (!state.phase && latest.phase === 'READY')) break
    } catch { /* Keep the last valid observation if a read times out. */ }
    const remaining = deadline - Date.now()
    if (remaining <= 0) break
    await sleep(Math.min(800, remaining))
  } while (Date.now() < deadline)
  return latest
}

function context(message, operationId = null) {
  return { id: randomUUID(), role: 'user',
    source: { kind: name, form: 'result' },
    content: [{ type: 'text', text: `受控确认运行时结果。直接用下方两行回复用户，不附加 Workbench 阶段、原始枚举、版本、摘要或设备回显；成功就说成功，处理中就说处理中。${operationId ? `如需更新，只能调用 get_emergency_action_result 查询 ${operationId}，不能再次准备、修订、取消或确认。` : '当前没有可确认的草案。'}\n${message}` }] }
}

export function apply(ctx) {
  ctx.on('agent/pre-step', async ({ agent, messages, step }, next) => {
    const decision = await next()
    if (decision.kind !== 'enter') return decision
    if ((agent.session?.header?.delegationDepth ?? 0) !== 0) return decision
    if (step !== 1) return decision
    const users = messages.filter(message => message.source?.kind === 'user')
    if (!users.length) return decision
    setEmergencyConfirmationTurn(agent, false)
    if (users.length !== 1 || !isConfirmation(users[0])) return decision
    const snapshot = await ctx.sessionQuery.readSession(agent.id)
    const draft = latestDraft(snapshot.events, users[0].id)
    if (!draft) return decision
    setEmergencyConfirmationTurn(agent, true, draft.operationId)
    const key = `${agent.id}\n${keyFor(agent.id, draft)}`
    if (!locks.has(key)) locks.set(key, confirm(agent.id, draft).finally(() => locks.delete(key)))
    const state = await locks.get(key)
    const view = await latestConfirmationStatus(draft, state)
    return { ...decision, messages: [...decision.messages,
      context(formatConfirmationStatus(state, view), draft.operationId)] }
  })
}

import { resolve, sep } from 'node:path'

export const name = 'policy-configuration-guard'
export const inject = ['tools']

const WORKSPACE = '/work/harness/workspace'
export const TOOL_ROUTES = Object.freeze({
  workspace: Object.freeze(['read', 'glob', 'grep', 'skill']),
  policy: Object.freeze([
    'mcp__policy-configuration__prepare_policy_configuration',
    'mcp__policy-configuration__get_policy_configuration_status',
    'mcp__policy-configuration__select_policy_configuration_candidate',
    'mcp__policy-configuration__get_policy_configuration_result',
  ]),
  inspection: Object.freeze([]),
  faultAnalysis: Object.freeze([]),
  delegates: Object.freeze([]),
  denied: Object.freeze([
    'mcp__policy-configuration__confirm_policy_configuration',
    'mcp__policy-configuration__decide_policy_configuration',
    'mcp__sec-ops__prepare_policy_configuration',
    'mcp__sec-ops__select_policy_configuration_candidate',
    'mcp__sec-ops__decide_policy_configuration',
  ]),
})

const ALLOWED = Object.freeze([...TOOL_ROUTES.workspace, ...TOOL_ROUTES.policy])
const ALLOWED_SET = new Set(ALLOWED)
const DENIED_SET = new Set(TOOL_ROUTES.denied)
const confirmationTurns = new WeakSet()
const deviceConstraints = new WeakMap()
export function setPolicyConfirmationTurn(agent, active) {
  if (active) confirmationTurns.add(agent)
  else confirmationTurns.delete(agent)
}
export function isPolicyConfirmationTurn(agent) {
  return confirmationTurns.has(agent)
}
export function deviceConstraintFromText(text) {
  if (typeof text !== 'string') return null
  const structured = text.match(/\bdevice_query\s*[=:：]\s*["'“‘]?([^\s,"'”’}]{1,80})/i)
  if (structured) return structured[1]
  const labeledOnDevice = text.match(/(?:请)?在\s*(?:防火墙|设备)\s+([^\s,，。；;]{1,80}?)\s*上(?:[，,\s]|放通|开通|新增|配置|$)/)
  if (labeledOnDevice) return labeledOnDevice[1]
  const onDevice = text.match(/(?:请)?在\s*([^\s,，。；;]{1,80}?)\s*上(?:[，,\s]|放通|开通|新增|配置|$)/)
  if (onDevice) return onDevice[1]
  const named = text.match(/(?:指定|使用)(?:的)?(?:防火墙|设备)(?:名称|ID|管理IP)?\s*[:：]?\s*([^\s,，。；;]{1,80})/i)
  return named?.[1] ?? null
}
export function setPolicyUserRequest(agent, text) {
  deviceConstraints.set(agent, deviceConstraintFromText(text))
}
const PREPARE = 'mcp__policy-configuration__prepare_policy_configuration'
const SUPPORTED_INTENT_FIELDS = new Set([
  'schema_version', 'policy_kind', 'operation', 'source', 'destination',
  'protocol', 'destination_port', 'target_external_id', 'device_query', 'validity', 'change_reason',
])

function validIpv4Host(selector) {
  if (!selector || selector.selector_type !== 'IP' || typeof selector.value !== 'string') return false
  const octets = selector.value.split('.')
  return octets.length === 4 && octets.every(octet =>
    /^(0|[1-9]\d{0,2})$/.test(octet) && Number(octet) <= 255)
}

function depthOf(exec) {
  return exec?.agent?.session?.header?.delegationDepth ?? 0
}

function insideWorkspace(path) {
  const target = resolve(WORKSPACE, path)
  return target === WORKSPACE || target.startsWith(WORKSPACE + sep)
}

export function visibleToolsForDepth(depth) {
  return depth === 0 ? ALLOWED : []
}

export function createSecurityOperationsGuard() {
  return {
    decide(exec) {
      const tool = exec?.name
      if (DENIED_SET.has(tool)) return '策略确认、决策和旧策略路由永久禁用'
      if (!exec?.agent) return '工具调用缺少 Agent 运行身份'
      if (confirmationTurns.has(exec.agent)) return '策略确认轮次禁止模型继续调用工具'
      if (depthOf(exec) !== 0) return '策略能力只允许主 Agent 调用'
      if (!ALLOWED_SET.has(tool)) return '未列入策略角色授权集合的工具被拒绝'
      if (tool === PREPARE) {
        const intent = exec.arguments?.body?.intent
        if (!intent || typeof intent !== 'object' || Array.isArray(intent)) {
          return '策略意图结构无效'
        }
        if (Object.keys(intent).some(field => !SUPPORTED_INTENT_FIELDS.has(field))) {
          return '不支持的意图字段，停止本次准备'
        }
        if (intent.operation !== 'ADD') {
          return '当前策略角色只允许新增策略，停止本次准备'
        }
        if (!validIpv4Host(intent.source) || !validIpv4Host(intent.destination) ||
            !['TCP', 'UDP'].includes(intent.protocol) ||
            !Number.isInteger(intent.destination_port) ||
            intent.destination_port < 1 || intent.destination_port > 65535) {
          return '策略参数不完整或无效，先补齐源和目的 IPv4、TCP/UDP 协议及目的端口'
        }
        if (Object.hasOwn(intent, 'device_query') &&
            (typeof intent.device_query !== 'string' ||
              !intent.device_query.trim() || intent.device_query.length > 80)) {
          return '指定设备线索无效，停止本次准备'
        }
        const requiredDevice = deviceConstraints.get(exec.agent)
        if (requiredDevice && intent.device_query !== requiredDevice) {
          return `用户指定设备必须原样传入 intent.device_query：${requiredDevice}`
        }
      }
      if (TOOL_ROUTES.workspace.includes(tool)) {
        const args = exec.arguments ?? {}
        for (const key of ['file_path', 'path', 'directory', 'cwd']) {
          const path = args[key]
          if (typeof path !== 'string') continue
          if (!insideWorkspace(path) || /(?:^|[/\\])\.env(?:$|[/\\.])/.test(path)) {
            return '文件读取仅限当前工作区的非凭据文件'
          }
        }
      }
      return undefined
    },
  }
}

export function apply(ctx) {
  const guard = createSecurityOperationsGuard()
  ctx.on('agent/pre-step', ({ agent, messages }, next) => {
    const latestUser = messages.filter(message => message.source?.kind === 'user').at(-1)
    if (latestUser) {
      const text = latestUser.content?.filter(item => item.type === 'text').map(item => item.text).join('') ?? ''
      setPolicyUserRequest(agent, text)
    }
    return next()
  })
  ctx.on('agent/created', ({ agent }) => {
    agent.ctx.tools.restrict({ allow: visibleToolsForDepth(agent?.session?.header?.delegationDepth ?? 0) })
  })
  ctx.tools.guard(exec => guard.decide(exec))
}

import { createHash, randomUUID } from 'node:crypto'
import { readFile, mkdir, writeFile, rename, chmod } from 'node:fs/promises'
import { join } from 'node:path'
import { setPolicyConfirmationTurn } from './policy-configuration-guard.mjs'

export const name = 'policy-confirmation-runtime'
export const inject = ['sessionQuery']

const RESULT = 'mcp__policy-configuration__get_policy_configuration_result'
const STATUS = 'mcp__policy-configuration__get_policy_configuration_status'
const STATE_DIR = '/var/lib/dsh/policy-confirmation-state'
const locks = new Map()

const textOf = message => message?.content?.filter(item => item.type === 'text').map(item => item.text).join('') ?? ''
const approval = message => message?.source?.kind === 'user' && textOf(message).trim() === '执行'

function projection(value) {
  if (!value || typeof value !== 'object') return null
  if (value.code === '200' && value.data && typeof value.data === 'object') return value.data
  return null
}

function resultOf(event) {
  const message = event?.data?.message
  if (message?.source?.kind !== 'tool' || message.isError) return null
  const block = message.content?.find(item => item.type === 'tool-result' && item.toolCallId === message.source.callId)
  if (block?.isError) return null
  const content = block ? block.content : message.content
  const raw = content?.find(item => item.type === 'text')?.text
  try { return projection(JSON.parse(raw)) } catch { return null }
}

export function latestDraft(events) {
  const calls = new Map()
  const projections = []
  const userEvents = []
  for (const event of events) {
    if (event.type === 'user/message' && event.data?.source?.kind === 'user') userEvents.push(event)
    if (event.type === 'tool/call') calls.set(event.data?.callId, event.data)
    if (event.type !== 'tool/result') continue
    const call = calls.get(event.data?.message?.source?.callId)
    if (!call || ![RESULT, STATUS].includes(call.name)) continue
    let args
    try { args = JSON.parse(call.arguments) } catch { continue }
    const value = resultOf(event)
    if (value && args?.operationId === value.operation_id) projections.push({ ...value, seq: event.seq, name: call.name })
  }
  const current = projections.at(-1)
  const newerUsers = current ? userEvents.filter(event => event.seq > current.seq) : []
  // The current approval may already be in the session snapshot at pre-step.
  if (!current || newerUsers.length > 1 ||
      (newerUsers.length === 1 && !approval(newerUsers[0].data)) ||
      current.task_status !== 'DRAFT' ||
      current.confirmation_required !== true || current.result_code !== 'DRAFT_READY' ||
      typeof current.operation_id !== 'string' ||
      !/^sha256:[0-9a-f]{64}$/.test(current.candidate_digest ?? '')) return null
  if (projections.some(item => item.operation_id === current.operation_id &&
      item.candidate_digest && item.candidate_digest !== current.candidate_digest)) return null
  return { operationId: current.operation_id, candidateDigest: current.candidate_digest, taskId: current.task_id }
}

export function confirmationArguments(sessionId, draft) {
  const material = `${sessionId}\n${draft.operationId}\n${draft.candidateDigest}`
  return {
    operationId: draft.operationId,
    body: {
      request_id: `policy-confirmation-${createHash('sha256').update(material).digest('hex').slice(0, 32)}`,
      candidate_digest: draft.candidateDigest,
    },
  }
}

function statePath(sessionId, draft) {
  const key = createHash('sha256').update(`${sessionId}\n${draft.operationId}\n${draft.candidateDigest}`).digest('hex')
  return join(STATE_DIR, `${key}.json`)
}

async function loadState(path) {
  try { return JSON.parse(await readFile(path, 'utf8')) } catch { return null }
}

async function saveState(path, value) {
  await mkdir(STATE_DIR, { recursive: true, mode: 0o700 })
  const temporary = `${path}.${randomUUID()}.tmp`
  await writeFile(temporary, JSON.stringify(value), { mode: 0o600, flag: 'wx' })
  await chmod(temporary, 0o600)
  await rename(temporary, path)
}

function decodeResponse(raw, contentType) {
  if (!raw.trim()) return null
  if (!contentType.includes('text/event-stream')) return JSON.parse(raw)
  const lines = raw.split(/\r?\n/).filter(line => line.startsWith('data:'))
  if (!lines.length) throw new Error('MCP SSE 响应缺少 data')
  return JSON.parse(lines.at(-1).slice(5).trim())
}

class RetryableError extends Error {}

async function post(url, token, payload, sessionId, timeoutMs) {
  const headers = {
    'Content-Type': 'application/json',
    Accept: 'application/json, text/event-stream',
    Authorization: `Bearer ${token}`,
  }
  if (sessionId) headers['Mcp-Session-Id'] = sessionId
  let response
  try {
    response = await fetch(url, {
      method: 'POST', headers, body: JSON.stringify(payload),
      signal: AbortSignal.timeout(timeoutMs),
    })
  } catch { throw new RetryableError('MCP 传输失败或超时') }
  if (response.status === 503) throw new RetryableError('MCP 暂时不可用')
  if (!response.ok) throw new Error(`MCP 请求被拒绝（HTTP ${response.status}）`)
  const body = decodeResponse(await response.text(), response.headers.get('content-type') ?? '')
  return { body, sessionId: response.headers.get('mcp-session-id') }
}

function findProjection(value) {
  if (value?.error) throw new Error('MCP tools/call 返回 JSON-RPC 错误')
  const queue = [value]
  while (queue.length) {
    const item = queue.shift()
    if (typeof item === 'string') {
      try { queue.push(JSON.parse(item)) } catch { /* Not JSON. */ }
    } else if (Array.isArray(item)) queue.push(...item)
    else if (item && typeof item === 'object') {
      if (item.isError === true) throw new Error('MCP 工具返回业务错误')
      if (item.operation_id && item.candidate_digest && item.confirmation && item.execution) return item
      queue.push(...Object.values(item))
    }
  }
  throw new Error('MCP 响应缺少策略确认联合投影')
}

export function validateConfirmation(value, draft) {
  const item = findProjection(value)
  if (item.operation_id !== draft.operationId || item.candidate_digest !== draft.candidateDigest ||
      item.confirmation?.accepted !== true ||
      typeof item.confirmation.approval_receipt_id !== 'string' ||
      !item.confirmation.approval_receipt_id.trim() ||
      !item.execution || typeof item.execution !== 'object' ||
      !['NONE', 'EXECUTION'].includes(item.failure_scope) ||
      typeof item.result_markdown !== 'string' || !item.result_markdown.trim()) {
    throw new Error('策略确认联合投影缺少有效回执或与 DRAFT 绑定不一致')
  }
  return item
}

async function callOnce(args, draft, deadline) {
  const url = process.env.POLICY_CONFIGURATION_MCP_URL
  const token = process.env.SEC_OPS_MCP_TOKEN
  if (!url || !token) throw new Error('策略 MCP 地址或凭据未配置')
  const send = (payload, sessionId) => post(url, token, payload, sessionId, Math.min(30000, Math.max(100, deadline - Date.now())))
  const initialized = await send({
    jsonrpc: '2.0', id: 1, method: 'initialize',
    params: { protocolVersion: '2025-03-26', capabilities: {}, clientInfo: { name: 'dsh-policy-confirmation', version: '1' } },
  })
  if (!initialized.body?.result) throw new Error('MCP initialize 未返回有效能力')
  const mcpSessionId = initialized.sessionId
  await send({ jsonrpc: '2.0', method: 'notifications/initialized' }, mcpSessionId)
  const called = await send({
    jsonrpc: '2.0', id: 2, method: 'tools/call',
    params: { name: 'confirm_policy_configuration', arguments: args },
  }, mcpSessionId)
  return validateConfirmation(called.body, draft)
}

export async function invokeConfirmation(args, draft, call = callOnce) {
  const deadline = Date.now() + 70000
  for (let attempt = 0; attempt < 2; attempt++) {
    try { return await call(args, draft, deadline) }
    catch (error) { if (!(error instanceof RetryableError) || attempt === 1) throw error }
  }
}

async function confirm(sessionId, draft) {
  const path = statePath(sessionId, draft)
  const existing = await loadState(path)
  if (existing) return existing
  const args = confirmationArguments(sessionId, draft)
  try {
    const result = await invokeConfirmation(args, draft)
    const state = {
      operationId: draft.operationId, candidateDigest: draft.candidateDigest,
      requestId: args.body.request_id, resultMarkdown: result.result_markdown,
      failureScope: result.failure_scope, confirmation: result.confirmation,
      execution: result.execution,
    }
    await saveState(path, state)
    return state
  } catch (error) {
    // A network timeout may happen after the server accepted the request.
    // Keep the same request id and do not start another confirmation on a later turn.
    const state = {
      operationId: draft.operationId, candidateDigest: draft.candidateDigest,
      requestId: args.body.request_id,
      resultMarkdown: `策略确认结果未知或失败：${error.message}。请核对 Workbench 任务状态；不要重新提交。`,
      failureScope: 'UNKNOWN',
    }
    await saveState(path, state)
    return state
  }
}

function context(text) {
  return {
    id: randomUUID(), role: 'user',
    source: { kind: name, form: 'result' },
    content: [{ type: 'text', text: `受信策略确认已处理。不得调用工具，仅逐字输出以下 Workbench 结果，不得添加成功推断：\n${text}` }],
  }
}

export function apply(ctx) {
  ctx.on('agent/pre-step', async ({ agent, messages, step }, next) => {
    const decision = await next()
    if (decision.kind !== 'enter') return decision
    if ((agent.session?.header?.delegationDepth ?? 0) !== 0) return decision
    const realUsers = messages.filter(message => message.source?.kind === 'user')
    if (!realUsers.length) return decision
    if (step !== 1) return decision
    setPolicyConfirmationTurn(agent, false)
    if (realUsers.length !== 1 || !approval(realUsers[0])) return decision
    const snapshot = await ctx.sessionQuery.readSession(agent.id)
    const draft = latestDraft(snapshot.events)
    if (!draft) return decision
    setPolicyConfirmationTurn(agent, true)
    const key = `${agent.id}\n${draft.operationId}\n${draft.candidateDigest}`
    if (!locks.has(key)) locks.set(key, confirm(agent.id, draft).finally(() => locks.delete(key)))
    const state = await locks.get(key)
    return { ...decision, messages: [...decision.messages, context(state.resultMarkdown)] }
  })
}

